      </thead>
      <tbody hlmTBody>
        @for (row of vm.rows(); track row.hero.id) {
          <tr hlmTr>
            <td hlmTd>
              <div class="roster__identity">
                <hlm-avatar size="sm">
                  <span hlmAvatarFallback>{{ row.initials }}</span>
                </hlm-avatar>
                <div class="roster__names">
                  <a hlmBtn variant="link" size="sm" class="roster__name" [routerLink]="['/detail', row.hero.id]">
                    {{ row.hero.name }}
                  </a>
                  <span hlmMuted>{{ row.hero.id }}</span>
                </div>
              </div>
            </td>
            <td hlmTd>
              <span hlmBadge variant="outline">{{ row.hero.powerClass }}</span>
            </td>
            <td hlmTd>{{ row.hero.powerIndex }}</td>
            <td hlmTd>
              <span hlmBadge [variant]="row.statusVariant">{{ row.hero.status }}</span>
            </td>
            <td hlmTd>{{ row.hero.clearance }}</td>
            <td hlmTd>
              <div class="roster__actions">
                <a
                  hlmBtn
                  variant="ghost"
                  size="icon-sm"
                  hlmTooltip="Edit hero"
                  [routerLink]="['/detail', row.hero.id]"
                  [attr.aria-label]="'Edit ' + row.hero.name"
                >
                  <ng-icon hlmIcon name="lucidePencil" />
                </a>
              </div>
            </td>
          </tr>
        } @empty {
          <tr hlmTr>
            <td hlmTd colspan="6">No heroes match these filters.</td>
          </tr>
        }
      </tbody>
    </table>
  </div>

  <div class="roster__summary">
    <p hlmSmall aria-live="polite">{{ vm.summary() }}</p>
    <p hlmMuted>Sorted by power</p>
  </div>
</section>
