mkdir -p "$TEMP/hd-check" && cat > "$TEMP/hd-check/check.mjs" <<'EOF'
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join } from 'node:path';
import { chromium } from 'file:///D:/Repos/angular-jig/node_modules/playwright/index.mjs';

const root = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const types = { '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html', '.json': 'application/json', '.svg': 'image/svg+xml' };
const server = createServer(async (req, res) => {
  const path = decodeURIComponent(new URL(req.url, 'http://x').pathname);
  let file = join(root, path);
  try { if (!(await stat(file)).isFile()) throw new Error(); } catch { file = join(root, 'index.html'); }
  res.setHeader('content-type', types[extname(file)] ?? 'application/octet-stream');
  res.end(await readFile(file));
}).listen(4311);

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 375, height: 900 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
const results = [];
const check = (name, ok) => results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}`);

try {
  await page.goto('http://localhost:4311/detail/HRO-0007', { waitUntil: 'networkidle' });
  check('heading shows hero name', (await page.locator('h1').first().textContent())?.includes('Silverwing'));

  // Retire: open, cancel, reopen, confirm.
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  const dialog = page.getByRole('dialog');
  await dialog.waitFor({ state: 'visible' });
  check('retire dialog shows title', (await dialog.textContent())?.includes('Retire Silverwing?'));
  await dialog.getByRole('button', { name: 'Cancel' }).click();
  await dialog.waitFor({ state: 'hidden' });
  check('cancel closes retire dialog', true);

  // Edit: an invalid name shows the schema message, a valid one saves.
  await page.getByRole('button', { name: 'Edit', exact: true }).click();
  await page.locator('#hero-name').fill('   ');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  const saved0 = await page.getByRole('status').count();
  check('blank name is rejected (no saved notice)', saved0 === 0);
  check('blank name shows a field error', (await page.locator('hlm-field-error').count()) > 0);
  await page.locator('#hero-name').fill('Silverwing Prime');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.getByRole('status').waitFor({ state: 'visible' });
  check('valid save shows saved notice', true);
  check('save updates heading', (await page.locator('h1').first().textContent())?.includes('Silverwing Prime'));

  // Confirmed retire removes the hero and returns to the roster.
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await dialog.waitFor({ state: 'visible' });
  await dialog.getByRole('button', { name: 'Retire hero' }).click();
